import { runItem } from './run-item.mjs';
export async function mapLimit(items, limit, mapper) {
  if (!items.length) return [];
  if (limit < 1) throw new RangeError('limit must be positive');
  const results = [];
  for (let offset = 0; offset < items.length; offset += limit) {
    const batch = items.slice(offset, offset + limit);
    await Promise.all(batch.map(async (value, index) => {
      results.push(await runItem(mapper, value, index));
    }));
  }
  return results;
}

